-- Se agregan lecciones sin modificar las evidencias ni el estado de matrículas existentes.
UPDATE leccion_curso SET numero=8 WHERE id IN ('c1000000-0000-4000-8000-000000000006','c1000000-0000-4000-8000-000000000012');
UPDATE curso SET duracion_minutos=(SELECT SUM(l.duracion_minutos) FROM leccion_curso l WHERE l.curso_id=curso.id) WHERE codigo IN ('ROBOTICA-INICIAL','COSMOS-INICIAL');
